EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Reference TRMM kernel: B[i,j] = alpha * (B[i,j] + sum_{k=i+1}^{m-1} A[k,i] * B[k,j])
@proc
def kernel_trmm_base(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    for i in seq(0, m):
        for j in seq(0, n):
            for k in seq(i + 1, m):
                B[i, j] += A[k, i] * B[k, j]
            B[i, j] = alpha * B[i, j]


# Start from the reference kernel and build an optimized version.
kernel_trmm = rename(kernel_trmm_base, "kernel_trmm")

# 1) Fission the inner j-loop into:
#    - one part that accumulates the triangular product
#    - one part that scales by alpha
# This exposes a pure triangular update phase that we can reorder and tile.
j_loop = kernel_trmm.find_loop("j")
j_body = j_loop.body()
gap = j_body[0].after()
kernel_trmm = fission(kernel_trmm, gap)

# After fission, we effectively have:
#   for i:
#     for j:
#       for k: B[i,j] += A[k,i] * B[k,j]
#   for i:
#     for j:
#       B[i,j] = alpha * B[i,j]

# 2) In the triangular update phase, reorder the (j, k) loops to (k, j):
#    This gives, for the first phase:
#       for i:
#         for k:
#           for j:
#             B[i,j] += A[k,i] * B[k,j]
#    Now j is innermost, so we stream through B[* , j] along its
#    contiguous second dimension, improving spatial locality.
kernel_trmm = reorder_loops(kernel_trmm, "j k")

# 3) Hoist A[k, i] into a scalar temporary so it is loaded once per (i,k)
#    instead of once per (i,k,j). This reduces pressure on the cache/memory
#    subsystem and lets the compiler keep the value in a register.
exprs = kernel_trmm.find_all("A[k, i]")
kernel_trmm = bind_expr(kernel_trmm, exprs, "a_ik")

# 4) Tile the j dimension (columns of B) in both phases to improve cache
#    locality and expose a strip-mined inner loop amenable to unrolling.
tile_j = 32

# First j-loop (inside the (i,k) update nest).
kernel_trmm = divide_loop(kernel_trmm, "j", tile_j, ("jo", "ji"), tail="guard")

# Second j-loop (the alpha-scaling phase).
kernel_trmm = divide_loop(kernel_trmm, "j #1", tile_j, ("jo", "ji"), tail="guard")

# 5) Unroll the inner j-tile loops to expose instruction-level parallelism
#    within each tile.
kernel_trmm = unroll_loop(kernel_trmm, "ji")
kernel_trmm = unroll_loop(kernel_trmm, "ji #1")

