#    Different columns of B are independent, so OpenMP parallelization
#    over jo is safe and effective on multi-core CPUs.
kernel_trmm = parallelize_loop(kernel_trmm, "jo")
kernel_trmm = parallelize_loop(kernel_trmm, "jo #1")

# 7) Final clean-up: simplify expressions and remove any dead code.
kernel_trmm = simplify(kernel_trmm)
